<?php require_once __DIR__.'/../../middleware/bootstrap.php';require_once __DIR__.'/../../config/database.php';$u=require_login();$d=body();$s=$pdo->prepare("SELECT price FROM packages WHERE id=? AND status='active'");$s->execute([(int)($d['package_id']??0)]);$p=$s->fetch();$date=$d['travel_date']??'';$n=(int)($d['travellers']??0);if(!$p||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date<date('Y-m-d')||$n<1||$n>20)json_out(['message'=>'Choose a valid trip, future date and 1–20 travelers.'],422);$s=$pdo->prepare('INSERT INTO bookings(user_id,package_id,travel_date,travellers,total_amount,special_requirements) VALUES(?,?,?,?,?,?)');$s->execute([$u['id'],$d['package_id'],$date,$n,$p['price']*$n,substr(trim($d['special_requirements']??''),0,2000)]);json_out(['message'=>'Booking received.','booking_id'=>$pdo->lastInsertId()],201);
